    if not col_lines:
        col_lines = list(range(0, w, 6))

    # Output cells correspond to successive lattice intervals. Colors
    # explicitly marked on the separator lines are retained; other cells
    # take the repeated interior color.
    nr = max(1, len(row_lines) - 1)
    nc = max(1, len(col_lines) - 1)
    out = [[background for _ in range(nc)] for _ in range(nr)]
    for i, r in enumerate(row_lines):
        if i >= nr:
            continue
        for j, c in enumerate(col_lines):
            if j >= nc:
                continue
            v = grid[r][c]
            if v != background:
                out[i][j] = v
    return out
