def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    interior = max(counts, key=counts.get)

    # Sample the colored junctions on the interior grid lines. The outer
    # border is omitted; each junction becomes one output cell.
    row_lines = [r for r in range(h) if all(v != interior for v in grid[r])]
    col_lines = [c for c in range(w)
                 if all(grid[r][c] != interior for r in range(h))]
    if len(row_lines) > 2:
        row_lines = row_lines[1:-1]
    if len(col_lines) > 2:
        col_lines = col_lines[1:-1]

    return [[grid[r][c] if grid[r][c] != interior else interior
             for c in col_lines] for r in row_lines]
